(* [comment removed for export] *)
Definition kin_post (kidx n k S1 : Z) (ra sp gp tp s0 s1 a6 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 x96 : word)
    (F0 : bvmap 5 word) (m0 : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a7' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem) (ks' : list word),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 kidx) a1' (Z_to_bv 64 1) (Z_to_bv 64 n) (Z_to_bv 64 1) (Z_to_bv 64 k) a6 a7'
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 0xcfee8) fc' None m' (seg_rom asegs)
    /\ fs_agree F0 F' /\ frm0 fc' /\ munch [(kidx, kidx + 1024); (S1 + 96, S1 + 104)] m0 m' /\ wmono asegs m0 m' /\ mem_inv asegs m'
    /\ u32arr asegs m' kidx ks' /\ kidx_ok 10 ks' /\ wr_at asegs m' kidx 1024 /\ acc asegs m' kidx 1024 /\ rw_cells asegs m' (S1 + 96) [C8 x96].

Lemma kidx_inner : forall (j : nat) (i n k : Z)
    (ra sp gp tp t1 t2 s0 s1 a6 s2 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 x96 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kidx S1 : Z) (ks : list word),
